secureScript.script:
import groovy.json.JsonSlurper
def folder = new File("/backups/sites")
if (folder.exists() && folder.isDirectory()) {
    def files = folder.listFiles({ file -> file.name.endsWith(".json") } as FileFilter)
    if (files) {
        def slurper = new JsonSlurper()
        def sites = []
        files.each { file ->
            try {
                def metadata = slurper.parse(file)
                if (metadata.status == "enabled") {
                    sites.add(file.name.minus(".json"))
                }
            } catch (e) {}
        }
        return sites ? sites.sort() : ["No active sites found"]
    }
}
return ["No active sites found"]

import java.io.File

def csrBasePath = "/site-data/csr-certs"

if (!commonName?.trim()) {
    return ["Select commonName first"]
}

def keyDir = new File("${csrBasePath}/${commonName}")

if (!keyDir.exists()) {
    return ["Directory not found: ${keyDir.absolutePath}"]
}

if (!keyDir.isDirectory()) {
    return ["Not a directory: ${keyDir.absolutePath}"]
}

def keys = keyDir.listFiles()
        ?.findAll { it.isFile() && it.name.endsWith(".key.pem") }
        ?.collect { it.name }
        ?: []

// Sort newest first based on date in filename
keys.sort { a, b ->
    def r = /_(\d{4}-\d{2}-\d{2})\.key\.pem$/
    def da = (a =~ r).find() ? (a =~ r)[0][1] : "0000-00-00"
    def db = (b =~ r).find() ? (b =~ r)[0][1] : "0000-00-00"
    db <=> da
}

if (keys.isEmpty()) {
    return ["No private keys found for ${commonName}"]
}

keys.add(0, "Select a private key...")
return keys
